export const rules=[['INPUT-01','Input gate','Validate profile, document types and size.'],['STP-01','ML eligibility','Standard class, calibrated confidence ≥ 0.95, in-distribution, complete evidence and no business-rule referral.'],['EVID-01','Document gate','Missing, conflicting or unreadable evidence blocks automatic acceptance.'],['REF-01','Business referral','Age > 75, life cover > SGD 1m, smoking or declared conditions require review in this demo.'],['HARNESS-01','Reasoning harness','Retrieve context → structured recommendation → citation and schema validation → at most one revision.'],['GUARD-01','Guardrails','Treat document instructions as untrusted; validate response structure and source IDs; fail closed.'],['HUMAN-01','Decision authority','Complex-path results are recommendations. An underwriter records the final decision and reason.']];
export function referral(p){return p.age>75||(p.product==='Life'&&p.cover>1000000)||p.smoker||p.condition!=='none'}
export function eligible(p,ml,evidence){return ml.available===true&&ml.standard===true&&ml.calibrated===true&&Number.isFinite(ml.confidence)&&ml.confidence>=.95&&ml.confidence<=1&&ml.ood===false&&evidence===true&&!referral(p)}
export function mockML(p){if(p.scenario==='ml_error')return {available:false,error:'Simulated ML endpoint timeout',model:'historical-risk-demo-v1'};return {available:true,standard:!referral(p),calibrated:true,confidence:referral(p)?.74:.98,ood:p.scenario==='ood',model:'historical-risk-demo-v1',note:'Scripted output; no trained ML model is running.'}}
export function mockEvidence(p,uploaded=[]){return {complete:p.evidence,findings:[{id:'DOC-1',source:'Synthetic medical report',text:p.condition==='none'?'No declared conditions; sample report contains no referral flags.':p.condition==='controlled'?'Stable condition declared; longitudinal clinical evidence requires review.':'Complex history requires clinician evidence and manual review.'},{id:'DOC-2',source:'Synthetic blood test',text:'Illustrative sample only; no clinical interpretation is performed.'}],warnings:uploaded.length?['Uploaded files are NOT read by AI in mock mode. Synthetic evidence is used.']:[]}}
export const mockContext=()=>({sources:[{id:'INT-1',type:'internal',title:'Demo underwriting manual',excerpt:'Refer declared conditions and high life cover for manual review.'},{id:'OKF-1',type:'knowledge',title:'Demo evidence relationship graph',excerpt:'Declaration → condition → required report → review rule.'},{id:'EXT-1',type:'external',title:'Synthetic external reference',excerpt:'An external evidence provider would return attributable data here.'},{id:'WEB-1',type:'web',title:'Simulated internet search result',excerpt:'No live web search has been performed.'}],note:'All sources are fictional placeholders.'});
